<script setup lang="ts">
import{ref}from'vue';const question=ref(''),result=ref<any>(null),busy=ref(false),error=ref('');function sample(q:string){question.value=q}async function query(){busy.value=true;error.value='';result.value=null;try{const r=await fetch('/api/assistant/business-query',{method:'POST',headers:{Authorization:'Bearer '+sessionStorage.getItem('ops-token'),'Content-Type':'application/json'},body:JSON.stringify({question:question.value})}),b=await r.json();if(!r.ok)throw Error(b.message);result.value=b.data}catch(e){error.value=e instanceof Error?e.message:'查询失败'}finally{busy.value=false}}const labels:Record<string,string>={SERVICE_NAME:'服务',DISPLAY_NAME:'显示名称',OWNER_NAME:'负责人',CURRENT_VERSION:'当前版本',RUNTIME_STATUS:'运行状态',VERSION_NO:'版本',ENVIRONMENT:'环境',STATUS:'状态',RELEASED_AT:'发布时间',SUMMARY:'摘要',SYMPTOM:'故障现象',ROOT_CAUSE:'根因',RESOLUTION:'处理办法',OCCURRED_AT:'发生时间'};
</script>
<template><section><div class="assistant-head"><div><span class="eyebrow">CONTROLLED TOOL CALLING</span><h1>业务数据查询</h1><p class="muted">使用固定只读工具查询服务、发布和历史故障；不生成 SQL，不修改业务数据。</p></div></div><div class="tool-query"><form @submit.prevent="query"><textarea v-model="question" required rows="2" maxlength="300" placeholder="例如：order-service 最近有哪些发布记录？"/><button :disabled="busy||!question.trim()">{{busy?'正在调用工具…':'查询'}}</button></form><div class="tool-samples"><button @click="sample('order-service 当前版本和负责人是谁？')">查询服务信息</button><button @click="sample('order-service 最近有哪些发布记录？')">查询最近发布</button><button @click="sample('order-service 有哪些历史故障和根因？')">查询历史故障</button></div></div><p v-if="error" class="banner error">{{error}}</p><div v-if="result" class="tool-result"><div class="tool-proof"><div><small>实际调用工具</small><strong>{{result.toolName}}</strong></div><div><small>受控参数</small><strong>service = {{result.serviceName}}</strong></div><div><small>返回记录</small><strong>{{result.resultCount}}</strong></div></div><p class="tool-explanation">{{result.explanation}}</p><article v-for="(row,i) in result.rows" class="tool-row"><b>#{{i+1}}</b><dl><template v-for="(value,key) in row"><dt>{{labels[String(key)]||key}}</dt><dd>{{value??'未获取'}}</dd></template></dl></article></div><div v-else class="empty tool-empty"><div class="large-icon">⌘</div><h3>自然语言，受控执行</h3><p>当前只开放 service_info、latest_releases、recent_incidents 三个只读工具。</p></div></section></template>
